// Guards the installable-web-app wiring: the manifest, the icons it points at, and the
// links in the built page. These are generated by separate steps (`npm run icons` writes
// the PNGs, `npm run build` copies the manifest), so they drift silently without a check.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

interface ManifestIcon { src: string; sizes: string; type: string; purpose?: string }
interface Manifest { theme_color: string; icons: ManifestIcon[] }

const ROOT = path.join(import.meta.dirname, '..');
const docs = (f: string): string => path.join(ROOT, 'docs', f);
const read = (p: string): string => fs.readFileSync(p, 'utf8');

const SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

// width/height live in the IHDR data, which starts at byte 16 of every PNG
function pngSize(file: string): { width: number; height: number } {
  const b = fs.readFileSync(file);
  assert.ok(b.subarray(0, 8).equals(SIGNATURE), `${path.basename(file)} is not a PNG`);
  assert.equal(b.subarray(12, 16).toString('latin1'), 'IHDR');
  return { width: b.readUInt32BE(16), height: b.readUInt32BE(20) };
}

const manifest = JSON.parse(read(path.join(ROOT, 'src', 'manifest.webmanifest'))) as Manifest;

test('build copies the manifest into the Pages directory', () => {
  assert.deepEqual(JSON.parse(read(docs('manifest.webmanifest'))) as Manifest, manifest);
});

test('every manifest icon exists and matches its declared size', () => {
  assert.ok(manifest.icons.length > 0, 'manifest declares no icons');
  for (const icon of manifest.icons) {
    const { width, height } = pngSize(docs(icon.src));
    assert.equal(`${width}x${height}`, icon.sizes, `${icon.src} is ${width}x${height}`);
  }
});

test('manifest declares a maskable icon of at least 512px', () => {
  const maskable = manifest.icons.filter((i) => (i.purpose || '').split(' ').includes('maskable'));
  assert.ok(maskable.length, 'no maskable icon — Android crops the plain one to a circle');
  assert.ok(maskable.some((i) => pngSize(docs(i.src)).width >= 512));
});

test('the built page links the manifest and an apple-touch-icon that exists', () => {
  const html = read(docs('index.html'));
  assert.match(html, /<link rel="manifest" href="manifest\.webmanifest">/);
  const apple = html.match(/<link rel="apple-touch-icon" href="([^"]+)">/);
  assert.ok(apple, 'no apple-touch-icon link — iOS homescreen falls back to a screenshot');
  assert.deepEqual(pngSize(docs(apple![1]!)), { width: 180, height: 180 });
});

test('both builds carry an inline favicon that needs no external host', () => {
  for (const f of ['docs/index.html', 'dist/artifact.html']) {
    const html = read(path.join(ROOT, f));
    assert.match(html, /<link rel="icon" href="data:image\/svg\+xml,/, `${f} has no inline favicon`);
  }
});

test('theme colour agrees between the manifest and the page meta tag', () => {
  const meta = read(docs('index.html')).match(/<meta name="theme-color" content="([^"]+)">/);
  assert.ok(meta);
  assert.equal(meta[1], manifest.theme_color);
});
